#!/usr/bin/env node
/**
 * SEO/GEO Review gate — an AI reviewer that runs in CI on changed content.
 *
 * It does NOT generate SEO; it REVIEWS the SEO/GEO quality of the content in a PR
 * against a living rubric (seo-review/standards.md) + calibration (seo-review/calibration.md),
 * grounding FAQ answers ONLY against the page body. The model scores; THIS code decides the
 * gate (evaluatePageVerdict). Preview is generated by a separate CI job and is never affected.
 *
 * Modes (env SEO_REVIEW_MODE): "advisory" (default — always exit 0, comment-only) | "blocking".
 * Runtime: GitHub Actions ephemeral runner. Model: OpenRouter openai/gpt-5.5 via Vercel AI SDK.
 *
 * Usage:
 *   node scripts/seo-review.mjs                 # CI: review files changed vs GITHUB_BASE_REF
 *   node scripts/seo-review.mjs --all           # review every content file
 *   node scripts/seo-review.mjs <file.md> ...   # review specific file(s) (local testing)
 *
 * Pure helpers are exported for deterministic unit tests (the LLM call is injected/mocked).
 */
import { readFileSync, writeFileSync, appendFileSync, existsSync, readdirSync } from 'node:fs';
import { join, basename } from 'node:path';
import { execSync } from 'node:child_process';
import matter from 'gray-matter';
import { z } from 'zod';

const CONTENT_DIRS = ['src/content/guides', 'src/content/apps'];
const MEMORY_DIR = 'seo-review';
const STANDARDS_PATH = join(MEMORY_DIR, 'standards.md');
const CALIBRATION_PATH = join(MEMORY_DIR, 'calibration.md');
const DECISIONS_PATH = join(MEMORY_DIR, 'decisions.jsonl');
const REPORT_PATH = 'seo-review-report.md';
const MARKER = '<!-- seo-review-bot -->';
const MODEL = 'openai/gpt-5.5';
const MAX_FILES = Number(process.env.SEO_REVIEW_MAX_FILES || 25);

export const BLOCKING_IDS = ['faq_grounding', 'faq_wellformed', 'meta_description', 'faqpage_schema_readiness', 'title_quality'];
export const ADVISORY_IDS = ['h2_question_form', 'direct_answer_geo', 'internal_linking', 'keyword_intent_match', 'no_keyword_stuffing', 'faqs_present'];
export const CRITERION_IDS = [...BLOCKING_IDS, ...ADVISORY_IDS];

// Meta-description hard length window (blocking outside this; ideal 120–160 is the model's call).
const META_MIN = 50;
const META_MAX = 180;

// ---------------------------------------------------------------------------
// Zod schema — shared by generateObject and evaluatePageVerdict
// ---------------------------------------------------------------------------
const CriterionResult = z.object({
  id: z.enum(CRITERION_IDS),
  score: z.number().min(0).max(5),
  severity: z.enum(['none', 'low', 'medium', 'high']),
  passed: z.boolean(),
  rationale: z.string(),
});
const FaqGroundingItem = z.object({
  question: z.string(),
  groundingStatus: z.enum(['grounded', 'partially_grounded', 'ungrounded', 'overclaims']),
  problemQuote: z.string().optional(),
  bodySupport: z.string().optional(),
});
export const PageVerdictSchema = z.object({
  slug: z.string(),
  collection: z.enum(['guides', 'apps']),
  criteria: z.array(CriterionResult),
  faqGrounding: z.array(FaqGroundingItem),
  blockingIssues: z.array(z.string()),
  suggestions: z.array(z.string()),
  overallScore: z.number().min(0).max(5),
  modelPassRecommendation: z.boolean(),
});

// ---------------------------------------------------------------------------
// Pure helpers (exported, unit-tested)
// ---------------------------------------------------------------------------
const CONTENT_PATH_RE = /^src\/content\/(guides|apps)\/[^/]+\.md$/;

/** Filter an arbitrary list of repo paths down to reviewable content markdown. */
export function filterContentPaths(paths) {
  return paths.map((p) => p.trim()).filter((p) => CONTENT_PATH_RE.test(p));
}

/** Parse a raw markdown file into frontmatter + body + deterministic derived facts. */
export function buildReviewInput(raw, filePath) {
  const parsed = matter(raw);
  const fm = parsed.data || {};
  const body = parsed.content || '';
  const title = typeof fm.title === 'string' ? fm.title : '';
  const description = typeof fm.description === 'string' ? fm.description : '';
  const faqs = Array.isArray(fm.faqs) ? fm.faqs : [];
  const slug = basename(filePath, '.md');
  const collection = /\/apps\//.test(filePath) ? 'apps' : 'guides';
  const h1 = (body.match(/^#\s+(?!#)(.+)$/m) || [, ''])[1].trim();
  const h2Headings = [...body.matchAll(/^##\s+(?!#)(.+)$/gm)].map((m) => m[1].trim());
  const h3Headings = [...body.matchAll(/^###\s+(?!#)(.+)$/gm)].map((m) => m[1].trim());
  const wikilinkCount = (body.match(/\[\[wiki\//g) || []).length;
  return {
    slug,
    collection,
    frontmatter: fm,
    body,
    derived: {
      slug,
      collection,
      title,
      titleWithSuffix: `${title} | ChinaGuide.ai`,
      titleLength: `${title} | ChinaGuide.ai`.length,
      description,
      descriptionLength: description.length,
      descriptionMissing: description.trim() === '',
      faqs,
      faqCount: faqs.length,
      h1,
      h2Headings,
      h3Headings,
      wikilinkCount,
      bodyForGrounding: body,
    },
  };
}

/**
 * Fail-closed completeness check on the model output itself: every BLOCKING criterion
 * must be present in `criteria`, and `faqGrounding` must cover every FAQ on the page.
 * An incomplete verdict must never silently pass the gate.
 */
export function verdictCompleteness(verdict, derived) {
  const present = new Set((verdict.criteria || []).map((c) => c.id));
  const missingBlockingCriteria = BLOCKING_IDS.filter((id) => !present.has(id));
  const faqCount = derived.faqCount ?? (Array.isArray(derived.faqs) ? derived.faqs.length : 0);
  const groundedCount = new Set((verdict.faqGrounding || []).map((f) => f.question)).size;
  const groundingGap = Math.max(0, faqCount - groundedCount);
  return {
    missingBlockingCriteria,
    faqCount,
    groundedCount,
    groundingGap,
    complete: missingBlockingCriteria.length === 0 && groundingGap === 0,
  };
}

/** Apply the BLOCKING policy to an LLM verdict + machine-checked derived facts. */
export function evaluatePageVerdict(verdict, derived) {
  const byId = Object.fromEntries((verdict.criteria || []).map((c) => [c.id, c]));
  const blocking = [];
  const advisory = [];
  const completeness = verdictCompleteness(verdict, derived);

  // 1. faq_grounding — authoritative source is the per-FAQ grounding array.
  const badGrounding = (verdict.faqGrounding || []).filter(
    (f) => f.groundingStatus === 'ungrounded' || f.groundingStatus === 'overclaims',
  );
  if (badGrounding.length) {
    blocking.push({
      id: 'faq_grounding',
      detail: badGrounding.map(
        (b) => `"${b.question}" — ${b.groundingStatus}${b.problemQuote ? `: ${b.problemQuote}` : ''}`,
      ),
    });
  }
  // Fail-closed: the model must ground EVERY FAQ; missing/short coverage blocks.
  if (completeness.groundingGap > 0) {
    blocking.push({
      id: 'faq_grounding',
      detail: [
        `model verdict grounded only ${completeness.groundedCount}/${completeness.faqCount} FAQs — incomplete coverage (fail-closed)`,
      ],
    });
  }

  // 3. meta_description — machine length check first, then model quality.
  if (derived.descriptionMissing) {
    blocking.push({ id: 'meta_description', detail: ['description missing (site emits a generic fallback)'] });
  } else if (derived.descriptionLength < META_MIN || derived.descriptionLength > META_MAX) {
    blocking.push({
      id: 'meta_description',
      detail: [`description length ${derived.descriptionLength} out of hard bounds ${META_MIN}–${META_MAX} (ideal ~120–160)`],
    });
  } else if (byId.meta_description && byId.meta_description.passed === false) {
    blocking.push({ id: 'meta_description', detail: [byId.meta_description.rationale] });
  }

  // 2,4,5. model-judged blocking criteria.
  for (const id of ['faq_wellformed', 'faqpage_schema_readiness', 'title_quality']) {
    const c = byId[id];
    if (c && c.passed === false) blocking.push({ id, detail: [c.rationale] });
  }

  // Fail-closed: a BLOCKING criterion absent from the model output blocks under its own id
  // (skipped when a machine check already blocked that id, to avoid duplicates).
  for (const id of completeness.missingBlockingCriteria) {
    if (!blocking.some((b) => b.id === id)) {
      blocking.push({ id, detail: ['criterion missing from model output (fail-closed)'] });
    }
  }

  // advisory criteria — reported, never block.
  for (const id of ADVISORY_IDS) {
    const c = byId[id];
    if (c && c.passed === false) advisory.push({ id, detail: [c.rationale] });
  }

  return {
    slug: verdict.slug,
    collection: verdict.collection,
    pass: blocking.length === 0,
    blocking,
    advisory,
    overallScore: verdict.overallScore,
    suggestions: verdict.suggestions || [],
  };
}

export function aggregateResults(pages) {
  const blockingCount = pages.reduce((n, p) => n + p.blocking.length, 0);
  const advisoryCount = pages.reduce((n, p) => n + p.advisory.length, 0);
  return {
    overallPass: pages.every((p) => p.pass),
    pageCount: pages.length,
    blockingCount,
    advisoryCount,
    failedPages: pages.filter((p) => !p.pass).map((p) => p.slug),
    pages,
  };
}

/** mode: 'advisory' always 0; 'blocking' fails when any page blocks; infra errors fail closed in blocking. */
export function decideExitCode(aggregate, mode, { infraError = false } = {}) {
  if (mode === 'blocking') {
    if (infraError) return 1;
    return aggregate.overallPass ? 0 : 1;
  }
  return 0; // advisory
}

export function renderMarkdownReport(aggregate, { mode, infraError = false } = {}) {
  const lines = [MARKER];
  const blockLabel = mode === 'blocking' ? '⛔ BLOCKING' : '⛔ WOULD BLOCK (advisory)';
  if (infraError) {
    lines.push(`## 🟥 SEO/GEO review could not complete`);
    lines.push('', 'The review hit an infrastructure error (LLM/API). ' + (mode === 'blocking' ? 'Failing closed.' : 'Advisory — not blocking.'));
    return lines.join('\n');
  }
  const head = aggregate.overallPass
    ? `## ✅ SEO/GEO review: PASS (${aggregate.pageCount} page${aggregate.pageCount === 1 ? '' : 's'})`
    : `## ${mode === 'blocking' ? '❌' : '⚠️'} SEO/GEO review: ${aggregate.blockingCount} blocking · ${aggregate.advisoryCount} advisory`;
  lines.push(head, '');
  if (mode === 'advisory') lines.push('_Advisory mode — this check does not block merge yet. Issues marked **WOULD BLOCK** are what will be enforced once hardened._', '');

  for (const p of aggregate.pages) {
    const status = p.pass ? '✅' : (mode === 'blocking' ? '❌' : '⚠️');
    lines.push(`### ${status} \`${p.collection}/${p.slug}\` — score ${p.overallScore}/5`);
    if (p.blocking.length) {
      lines.push(`**${blockLabel}:**`);
      for (const b of p.blocking) for (const d of b.detail) lines.push(`- \`${b.id}\` — ${d}`);
    }
    if (p.advisory.length) {
      lines.push('**Advisory:**');
      for (const a of p.advisory) for (const d of a.detail) lines.push(`- \`${a.id}\` — ${d}`);
    }
    if (p.suggestions.length) {
      lines.push('<details><summary>Suggestions</summary>', '');
      for (const s of p.suggestions) lines.push(`- ${s}`);
      lines.push('</details>');
    }
    if (p.pass && !p.advisory.length && !p.suggestions.length) lines.push('_No issues._');
    lines.push('');
  }
  return lines.join('\n');
}

// ---------------------------------------------------------------------------
// Memory
// ---------------------------------------------------------------------------
export function loadMemory(read = (p) => (existsSync(p) ? readFileSync(p, 'utf8') : '')) {
  return { standards: read(STANDARDS_PATH), calibration: read(CALIBRATION_PATH) };
}

/** Parse the JSONL ledger (skipping blank/# lines) and return prior decisions for a slug. */
export function loadPageHistory(jsonlText, slug) {
  if (!jsonlText) return [];
  return jsonlText
    .split('\n')
    .map((l) => l.trim())
    .filter((l) => l && !l.startsWith('#'))
    .map((l) => {
      try {
        return JSON.parse(l);
      } catch {
        return null;
      }
    })
    .filter((d) => d && d.slug === slug);
}

// ---------------------------------------------------------------------------
// Prompts
// ---------------------------------------------------------------------------
export function buildSystemPrompt(standards, calibration) {
  return [
    'You are a strict, authoring-agnostic SEO/GEO REVIEWER for ChinaGuide.ai. You do NOT write or improve SEO — you REVIEW the SEO/GEO quality of content already in a pull request and return a structured verdict. You do not care who authored it.',
    '',
    'GROUNDING RULE (critical): the page BODY provided is the ONLY ground truth for judging FAQ answers. Do NOT use outside knowledge to rescue a claim. When support is unclear, do NOT mark it grounded. An answer that states something more strongly/absolutely than the body supports is "overclaims".',
    '',
    'Score each rubric criterion 0–5 with a one-sentence rationale and a `passed` boolean. COMPLETENESS IS MANDATORY: `criteria` must contain ALL 11 rubric criterion ids (an omitted criterion is treated as a failure by the host), and `faqGrounding` must contain exactly one item per FAQ, copying each question verbatim. Output ONLY the structured object. The host code — not you — decides the merge gate.',
    '',
    '=== STANDARDS (rubric) ===',
    standards || '(standards file missing)',
    '',
    '=== CALIBRATION (project tolerance — accepted/rejected edge cases) ===',
    calibration || '(no calibration yet)',
  ].join('\n');
}

export function buildUserPrompt(derived, history = []) {
  const faqBlock = derived.faqs.length
    ? derived.faqs.map((f, i) => `${i + 1}. Q: ${f.q}\n   A: ${f.a}`).join('\n')
    : '(no faqs on this page)';
  const histNote = history.length
    ? `\nPRIOR DECISIONS for this page (do not re-flag issues a human already accepted):\n${history
        .map((h) => `- ${h.verdict || ''}: ${(h.blocking || []).join('; ') || 'pass'}`)
        .join('\n')}\n`
    : '';
  return [
    `PAGE: ${derived.collection}/${derived.slug}`,
    `<title>: ${derived.titleWithSuffix} (length ${derived.titleLength})`,
    `META description: ${derived.descriptionMissing ? '(MISSING — generic fallback will be used)' : derived.description} (length ${derived.descriptionLength})`,
    `H1: ${derived.h1}`,
    `H2 headings:\n${derived.h2Headings.map((h) => `- ${h}`).join('\n') || '(none)'}`,
    `Internal wiki links: ${derived.wikilinkCount}`,
    histNote,
    `FAQs (rendered verbatim into the visible FAQ section AND FAQPage JSON-LD):\n${faqBlock}`,
    '',
    'PAGE BODY (ground truth — judge FAQ answers against THIS only):',
    '"""',
    derived.bodyForGrounding,
    '"""',
    '',
    'Review per the STANDARDS rubric. Return ALL 11 criteria. Ground every FAQ answer against the body above — faqGrounding must have one item per FAQ with the question copied verbatim. For pages with no faqs, mark faq_* criteria passed=true with rationale "no faqs" and return an empty faqGrounding array.',
  ].join('\n');
}

// ---------------------------------------------------------------------------
// LLM call (impure; injectable for tests)
// ---------------------------------------------------------------------------
async function defaultCallModel({ system, prompt }) {
  const { createOpenRouter } = await import('@openrouter/ai-sdk-provider');
  const { generateObject } = await import('ai');
  const openrouter = createOpenRouter({ apiKey: process.env.OPENROUTER_API_KEY });
  const { object } = await generateObject({
    model: openrouter.chat(MODEL),
    schema: PageVerdictSchema,
    temperature: 0,
    system,
    prompt,
  });
  return object;
}

export async function reviewPage(input, memory, { callModel = defaultCallModel, retries = 2 } = {}) {
  const system = buildSystemPrompt(memory.standards, memory.calibration);
  const prompt = buildUserPrompt(input.derived, input.history);
  let lastErr;
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const verdict = await callModel({ system, prompt });
      // ensure slug/collection are set even if model omits/varies
      verdict.slug = input.derived.slug;
      verdict.collection = input.derived.collection;
      // Incomplete verdict (missing blocking criteria / FAQs not all grounded): retry to let
      // the model self-correct. If retries run out, return it anyway — the deterministic
      // gate (evaluatePageVerdict) blocks incomplete verdicts, never silently passes them.
      if (!verdictCompleteness(verdict, input.derived).complete && attempt < retries) {
        lastErr = new Error('incomplete verdict from model');
        continue;
      }
      return verdict;
    } catch (err) {
      lastErr = err;
      if (attempt < retries) await new Promise((r) => setTimeout(r, 500 * (attempt + 1)));
    }
  }
  throw lastErr;
}

// ---------------------------------------------------------------------------
// Impure I/O helpers
// ---------------------------------------------------------------------------
function listAllContentFiles() {
  const out = [];
  for (const dir of CONTENT_DIRS) {
    if (!existsSync(dir)) continue;
    for (const f of readdirSync(dir)) if (f.endsWith('.md')) out.push(`${dir}/${f}`);
  }
  return out;
}

export function getChangedContentFiles(baseRef, { all = false } = {}) {
  if (all || !baseRef) return listAllContentFiles();
  let out = '';
  try {
    out = execSync(`git diff --name-only --diff-filter=ACMR origin/${baseRef}...HEAD`, { encoding: 'utf8' });
  } catch {
    out = execSync(`git diff --name-only --diff-filter=ACMR ${baseRef}...HEAD`, { encoding: 'utf8' });
  }
  return filterContentPaths(out.split('\n'));
}

function appendDecisions(results, mode) {
  const stamp = new Date().toISOString();
  for (const p of results) {
    const rec = {
      ts: stamp,
      slug: p.slug,
      collection: p.collection,
      verdict: p.pass ? 'pass' : 'blocked',
      mode,
      blocking: p.blocking.flatMap((b) => b.detail.map((d) => `${b.id}: ${d}`)),
    };
    try {
      appendFileSync(DECISIONS_PATH, JSON.stringify(rec) + '\n');
    } catch {
      /* non-fatal */
    }
  }
}

function writeReport(report) {
  writeFileSync(REPORT_PATH, report);
  if (process.env.GITHUB_STEP_SUMMARY) {
    try {
      appendFileSync(process.env.GITHUB_STEP_SUMMARY, report + '\n');
    } catch {
      /* non-fatal */
    }
  }
}

// ---------------------------------------------------------------------------
// main
// ---------------------------------------------------------------------------
async function main() {
  const mode = process.env.SEO_REVIEW_MODE === 'blocking' ? 'blocking' : 'advisory';
  const args = process.argv.slice(2);
  const all = args.includes('--all');
  const fileArgs = filterContentPaths(args.filter((a) => !a.startsWith('--')));

  if (!process.env.OPENROUTER_API_KEY) {
    const msg = '⏭️  OPENROUTER_API_KEY not set — skipping SEO/GEO review (soft pass).';
    console.log(msg);
    writeReport(`${MARKER}\n## ⏭️ SEO/GEO review skipped\n\n\`OPENROUTER_API_KEY\` not configured — review is inert until the secret is set.`);
    process.exit(0);
  }

  let files;
  if (fileArgs.length) files = fileArgs;
  else if (all) files = getChangedContentFiles(null, { all: true });
  else files = getChangedContentFiles(process.env.GITHUB_BASE_REF, { all: process.env.GITHUB_EVENT_NAME === 'workflow_dispatch' });

  if (!files.length) {
    console.log('✅ No content changes — SEO/GEO review not applicable.');
    writeReport(`${MARKER}\n## ✅ SEO/GEO review: no content changes`);
    process.exit(0);
  }

  let capped = files;
  let dropped = [];
  if (files.length > MAX_FILES) {
    capped = files.slice(0, MAX_FILES);
    dropped = files.slice(MAX_FILES);
    console.log(`⚠️  ${files.length} files changed — reviewing first ${MAX_FILES}, skipping ${dropped.length}.`);
  }

  const memory = loadMemory();
  const decisionsText = existsSync(DECISIONS_PATH) ? readFileSync(DECISIONS_PATH, 'utf8') : '';

  const results = [];
  let infraError = false;
  try {
    for (const file of capped) {
      const raw = readFileSync(file, 'utf8');
      const input = buildReviewInput(raw, file);
      input.history = loadPageHistory(decisionsText, input.slug);
      const verdict = await reviewPage(input, memory);
      results.push(evaluatePageVerdict(verdict, input.derived));
      console.log(`  reviewed ${file}`);
    }
  } catch (err) {
    infraError = true;
    console.error(`❌ SEO/GEO review infra error: ${err?.message || err}`);
  }

  const aggregate = aggregateResults(results);
  let report = renderMarkdownReport(aggregate, { mode, infraError });
  if (dropped.length) report += `\n> ⚠️ ${dropped.length} additional changed file(s) not reviewed this run (cap ${MAX_FILES}): ${dropped.join(', ')}`;
  writeReport(report);
  if (results.length) appendDecisions(results, mode);

  const code = decideExitCode(aggregate, mode, { infraError });
  console.log(`${code === 0 ? '✅' : '❌'} SEO/GEO review done — mode=${mode}, ${aggregate.blockingCount} blocking, exit ${code}.`);
  process.exit(code);
}

if (import.meta.url === `file://${process.argv[1]}`) main();
